use maho_rpc::{session_worker_client::receive_snapshot,session_worker_protocol::WorkerSnapshot,session_worker_signals::WorkerSignal};
#[test]fn reconcile_precedes_credit_and_settled_listener_follows_release(){let signal=WorkerSignal::default();let mut snapshot=None;let replacement=WorkerSnapshot{state:serde_json::json!({}),session_path:Some("/live".into()),live_session_paths:vec!["/live".into()],busy:false,handoff_busy:Some(false),streaming:false};let reconciled=std::cell::Cell::new(false);let settled=std::cell::Cell::new(false);receive_snapshot(&mut snapshot,replacement,&signal,true,|paths|{assert_eq!(paths,["/live"]);assert_eq!(signal.wait(std::time::Duration::ZERO),0);reconciled.set(true);},||{assert!(reconciled.get());assert_eq!(signal.wait(std::time::Duration::ZERO),1);settled.set(true);});assert!(settled.get());assert_eq!(snapshot.unwrap().session_path.as_deref(),Some("/live"));}
